CREATE TABLE public.spy_references(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, platform text NOT NULL DEFAULT 'Meta', original_url text NOT NULL DEFAULT '', library_url text NOT NULL DEFAULT '', copy text NOT NULL DEFAULT '', hook text NOT NULL DEFAULT '', cta text NOT NULL DEFAULT '', country text NOT NULL DEFAULT '', language text NOT NULL DEFAULT 'Português', niche text NOT NULL DEFAULT '', product text NOT NULL DEFAULT '', offer_id uuid REFERENCES public.offers(id), captured_at date NOT NULL DEFAULT current_date, notes text NOT NULL DEFAULT '', tags text[] NOT NULL DEFAULT '{}', archived boolean NOT NULL DEFAULT false, created_by uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.spy_references TO authenticated; GRANT ALL ON public.spy_references TO service_role;
ALTER TABLE public.spy_references ENABLE ROW LEVEL SECURITY;
CREATE POLICY spy_read ON public.spy_references FOR SELECT TO authenticated USING(public.is_member());
CREATE POLICY spy_write ON public.spy_references FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'spy')));
CREATE POLICY spy_edit ON public.spy_references FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'spy')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'spy'));
CREATE TABLE public.spy_favorites(user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), reference_id uuid NOT NULL REFERENCES public.spy_references(id), PRIMARY KEY(user_id,reference_id));
GRANT SELECT,INSERT,DELETE ON public.spy_favorites TO authenticated; GRANT ALL ON public.spy_favorites TO service_role;
ALTER TABLE public.spy_favorites ENABLE ROW LEVEL SECURITY;
CREATE POLICY favorites_own ON public.spy_favorites FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND public.is_member());
ALTER TABLE public.files ADD COLUMN spy_id uuid REFERENCES public.spy_references(id), ADD COLUMN profile_id uuid REFERENCES public.profiles(id);
ALTER TABLE public.demand_items ADD COLUMN source_spy_id uuid REFERENCES public.spy_references(id), ADD COLUMN performance_status text NOT NULL DEFAULT 'Não testado';
CREATE TABLE public.creative_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version_id uuid NOT NULL REFERENCES public.creative_versions(id), decision text NOT NULL CHECK(decision IN ('Aprovado','Ajustes solicitados')), notes text NOT NULL DEFAULT '', reviewer_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.creative_reviews TO authenticated; GRANT ALL ON public.creative_reviews TO service_role;
ALTER TABLE public.creative_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY reviews_read ON public.creative_reviews FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.creative_versions v WHERE v.id=version_id));
CREATE TABLE public.publications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version_id uuid NOT NULL REFERENCES public.creative_versions(id), ad_id text NOT NULL DEFAULT '', ad_url text NOT NULL DEFAULT '', campaign text NOT NULL DEFAULT '', ad_set text NOT NULL DEFAULT '', published_at date NOT NULL DEFAULT current_date, status text NOT NULL DEFAULT 'Publicado' CHECK(status IN ('Publicado','Pausado','Encerrado')), created_by uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.publications TO authenticated; GRANT ALL ON public.publications TO service_role;
ALTER TABLE public.publications ENABLE ROW LEVEL SECURITY;
CREATE POLICY publications_read ON public.publications FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'traffic') OR EXISTS(SELECT 1 FROM public.creative_versions v WHERE v.id=version_id));
CREATE POLICY publications_insert ON public.publications FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'traffic')) AND EXISTS(SELECT 1 FROM public.creative_reviews r WHERE r.version_id=publications.version_id AND r.decision='Aprovado' AND NOT EXISTS(SELECT 1 FROM public.creative_reviews newer WHERE newer.version_id=r.version_id AND newer.created_at>r.created_at)));
CREATE POLICY publications_update ON public.publications FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'traffic')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'traffic'));
CREATE TABLE public.performance_daily(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), offer_id uuid NOT NULL REFERENCES public.offers(id), item_id uuid REFERENCES public.demand_items(id), date date NOT NULL, currency text NOT NULL CHECK(currency IN ('BRL','USD','MXN','ARS','ZAR')), ad_spend numeric NOT NULL DEFAULT 0 CHECK(ad_spend>=0), revenue numeric NOT NULL DEFAULT 0 CHECK(revenue>=0), orders integer NOT NULL DEFAULT 0 CHECK(orders>=0), leads integer NOT NULL DEFAULT 0 CHECK(leads>=0), product_cost numeric NOT NULL DEFAULT 0 CHECK(product_cost>=0), delivery_cost numeric NOT NULL DEFAULT 0 CHECK(delivery_cost>=0), payment_fees numeric NOT NULL DEFAULT 0 CHECK(payment_fees>=0), other_cost numeric NOT NULL DEFAULT 0 CHECK(other_cost>=0), conversion_currency text CHECK(conversion_currency IN ('BRL','USD','MXN','ARS','ZAR')), conversion_rate numeric CHECK(conversion_rate>0), archived boolean NOT NULL DEFAULT false, created_by uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), CHECK((conversion_currency IS NULL)=(conversion_rate IS NULL)));
GRANT SELECT,INSERT,UPDATE ON public.performance_daily TO authenticated; GRANT ALL ON public.performance_daily TO service_role;
ALTER TABLE public.performance_daily ENABLE ROW LEVEL SECURITY;
CREATE POLICY performance_read ON public.performance_daily FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'traffic'));
CREATE POLICY performance_write ON public.performance_daily FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND public.has_role(auth.uid(),'admin'));
CREATE POLICY performance_edit ON public.performance_daily FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), item_id uuid REFERENCES public.demand_items(id), title text NOT NULL, body text NOT NULL DEFAULT '', event_key text UNIQUE, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notifications_read ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY notifications_update ON public.notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.can_read_demand(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.demand_items WHERE demand_id=_id AND (assigned_to=auth.uid() OR (public.has_role(auth.uid(),'traffic') AND status='Aprovado'))) $$;
CREATE POLICY items_traffic_read ON public.demand_items FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'traffic') AND status='Aprovado');
CREATE POLICY versions_traffic_read ON public.creative_versions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'traffic') AND EXISTS(SELECT 1 FROM public.demand_items i WHERE i.id=item_id AND i.status='Aprovado'));
CREATE POLICY files_extra_read ON public.files FOR SELECT TO authenticated USING((spy_id IS NOT NULL AND public.is_member()) OR profile_id=auth.uid() OR (item_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.demand_items i WHERE i.id=item_id AND i.source_spy_id IS NOT NULL AND public.is_member())) OR (public.has_role(auth.uid(),'traffic') AND EXISTS(SELECT 1 FROM public.creative_versions v JOIN public.creative_reviews r ON r.version_id=v.id WHERE v.file_id=files.id AND r.decision='Aprovado')));
CREATE POLICY files_extra_insert ON public.files FOR INSERT TO authenticated WITH CHECK(uploaded_by=auth.uid() AND ((spy_id IS NOT NULL AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'spy'))) OR (profile_id=auth.uid() AND purpose='avatar')));
CREATE POLICY objects_extra_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='dr-files' AND EXISTS(SELECT 1 FROM public.files f WHERE f.path=name));
CREATE POLICY objects_extra_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='dr-files' AND EXISTS(SELECT 1 FROM public.files f WHERE f.path=name AND f.uploaded_by=auth.uid()));
CREATE OR REPLACE FUNCTION public.review_creative(target_version uuid, verdict text, observation text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target_item uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Apenas administradores podem revisar'; END IF; IF verdict NOT IN ('Aprovado','Ajustes solicitados') THEN RAISE EXCEPTION 'Decisão inválida'; END IF; IF verdict='Ajustes solicitados' AND length(trim(observation))=0 THEN RAISE EXCEPTION 'Informe os ajustes necessários'; END IF; SELECT v.item_id INTO target_item FROM public.creative_versions v JOIN public.files f ON f.id=v.file_id JOIN storage.objects o ON o.name=f.path AND o.bucket_id='dr-files' WHERE v.id=target_version AND f.purpose='final'; IF target_item IS NULL THEN RAISE EXCEPTION 'Arquivo final não encontrado'; END IF; PERFORM 1 FROM public.demand_items WHERE id=target_item FOR UPDATE; INSERT INTO public.creative_reviews(version_id,decision,notes) VALUES(target_version,verdict,observation); UPDATE public.demand_items SET status=verdict WHERE id=target_item; END $$;
REVOKE ALL ON FUNCTION public.review_creative(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_creative(uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.validate_item_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN IF (to_jsonb(new)-'status') IS DISTINCT FROM (to_jsonb(old)-'status') THEN RAISE EXCEPTION 'Você só pode alterar o andamento de seus itens'; END IF; IF new.status NOT IN ('Em edição','Aguardando aprovação') THEN RAISE EXCEPTION 'Status não permitido para editor'; END IF; END IF; IF new.status='Aguardando aprovação' AND NOT EXISTS(SELECT 1 FROM public.creative_versions WHERE item_id=new.id) THEN RAISE EXCEPTION 'Anexe um arquivo final antes de enviar para aprovação'; END IF; IF new.status='Aprovado' AND NOT EXISTS(SELECT 1 FROM public.creative_versions v JOIN public.creative_reviews r ON r.version_id=v.id WHERE v.item_id=new.id AND r.decision='Aprovado') THEN RAISE EXCEPTION 'Aprove uma versão do arquivo final'; END IF; RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.notify_item_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF new.assigned_to IS NOT NULL AND (TG_OP='INSERT' OR new.assigned_to IS DISTINCT FROM old.assigned_to) THEN INSERT INTO public.notifications(user_id,item_id,title,body) VALUES(new.assigned_to,new.id,'Nova demanda atribuída',new.name); END IF; IF TG_OP='UPDATE' AND new.status IS DISTINCT FROM old.status THEN IF new.status='Aguardando aprovação' THEN INSERT INTO public.notifications(user_id,item_id,title,body) SELECT user_id,new.id,'Criativo enviado para aprovação',new.name FROM public.user_roles WHERE role='admin'; ELSIF new.status IN ('Aprovado','Ajustes solicitados') THEN IF new.assigned_to IS NOT NULL THEN INSERT INTO public.notifications(user_id,item_id,title,body) VALUES(new.assigned_to,new.id,new.status,new.name); END IF; IF new.status='Aprovado' THEN INSERT INTO public.notifications(user_id,item_id,title,body) SELECT user_id,new.id,'Criativo na fila de publicação',new.name FROM public.user_roles WHERE role='traffic'; END IF; END IF; END IF; RETURN new; END $$;
CREATE TRIGGER items_notify AFTER INSERT OR UPDATE ON public.demand_items FOR EACH ROW EXECUTE FUNCTION public.notify_item_change();
CREATE OR REPLACE FUNCTION public.refresh_deadline_notifications() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.notifications(user_id,item_id,title,body,event_key) SELECT i.assigned_to,i.id,CASE WHEN i.due_date<current_date THEN 'Demanda atrasada' ELSE 'Prazo próximo' END,i.name,'deadline:'||i.id||':'||current_date FROM public.demand_items i WHERE i.assigned_to=auth.uid() AND i.due_date<=current_date+1 AND i.status NOT IN ('Aprovado','Cancelado') ON CONFLICT(event_key) DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.refresh_deadline_notifications() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.refresh_deadline_notifications() TO authenticated;
CREATE INDEX spy_offer_idx ON public.spy_references(offer_id,captured_at); CREATE INDEX reviews_version_idx ON public.creative_reviews(version_id,created_at DESC); CREATE INDEX publications_version_idx ON public.publications(version_id); CREATE INDEX performance_offer_date_idx ON public.performance_daily(offer_id,date); CREATE INDEX notifications_user_idx ON public.notifications(user_id,created_at DESC); CREATE INDEX items_demand_idx ON public.demand_items(demand_id); CREATE INDEX files_entities_idx ON public.files(item_id,demand_id,offer_id);